function showHostControl(){if(!HST)return toast('Only the host can open Table Control.');$('game').classList.add('h');$('lobby').classList.add('h');$('hostControl').classList.remove('h');$('hostRoomCode').textContent=(activeRoom||'------').toUpperCase();renderHost();if(location.hash!=='#host')history.replaceState(null,'','#host')}
$('hudModeBtn').onclick=showHostControl;$('playerHudBtn').onclick=showBattlePage;document.querySelectorAll('[data-player-page]').forEach(b=>b.onclick=()=>setPlayerHudPage(b.dataset.playerPage));
document.querySelectorAll('[data-host-tab]').forEach(b=>b.onclick=()=>{hostTab=b.dataset.hostTab;document.querySelectorAll('[data-host-tab]').forEach(x=>x.classList.toggle('active',x===b));renderHost()});
function hostAdjustPlayer(id,kind){if(kind==='life')return numericControl('P'+id+' Life',st.life[id]??40,d=>{apply('life',{d},id,{source:'host-control'});renderHost()});if(kind==='poison')return numericControl('P'+id+' Poison',st.poison[id]||0,d=>{apply('counter',{k:'poison',d},id,{source:'host-control'});renderHost()});if(kind==='tax')return numericControl('P'+id+' Commander Tax',st.tax[id]||0,d=>{apply('counter',{k:'tax',d},id,{source:'host-control'});renderHost()});if(kind==='cmdCasts')return numericControl('P'+id+' Commander Casts',st.cmdCasts[id]||0,d=>{apply('counter',{k:'cmdCasts',d},id,{source:'host-control'});renderHost()})}
function hostCommanderDamage(defender){let sources=players.filter(p=>p.id!==defender);if(!sources.length)return toast('No commander sources available.');choice(sources.map(p=>'P'+p.id+' · '+(p.commander||'Commander')),pick=>{let m=pick.match(/^P(\d+)/),from=Number(m&&m[1]);if(!from)return;let key=MTGEngine.commanderKey(from),cur=(st.cmd[defender]||{})[key]||0;numericControl('P'+from+' Commander Damage → P'+defender,cur,d=>{apply('cmd',{from,commanderId:key,d},defender,{source:'host-control'});renderHost()})})}
function hostUndo(){let restored=MTGEngine.undo(st);if(!restored)return toast('Nothing to undo.');st=restored;sync();send({t:'state',st});renderHost();toast('Authoritative event undone.')}
function eventLabel(e){let p=e.payload||{};if(e.type==='PHASE106_BUYBACK_RESOLVED')return 'Buyback · returned to hand';if(e.type==='ADVENTURE_RESOLVED_TO_EXILE')return 'Adventure resolved · exile permission';if(e.type==='CAST_PERMISSION_GRANTED')return 'Cast permission · granted';if(e.type==='CAST_PERMISSION_REVOKED')return 'Cast permission · revoked';if(e.type==='TRACKED_CAST_NONPERMANENT_RESOLVED')return 'Tracked spell · resolved destination';if(e.type==='FACE_DOWN_PERMANENT_ENTERED')return String(p.mechanism||'FACE DOWN').toUpperCase()+' · entered face down';if(e.type==='PERMANENT_FACE_UP_SPECIAL_ACTION')return 'Turned face up · special action';if(e.type==='LINK_GROUP_CREATED')return 'Linked ability · group created';if(e.type==='LINK_CHOICE_RECORDED')return 'Linked choice · '+String(p.key||'choice');if(e.type==='LINK_EXILED_OBJECTS_RECORDED')return 'Linked exile · '+((p.objectIds||[]).length)+' object(s)';if(e.type==='LINK_COST_RECORDED')return 'Linked cost · '+String(p.key||'cost');if(e.type==='LIFE_CHANGED'||e.type==='LIFE_CHANGED_EXACT')return 'P'+p.playerId+' life '+(String(p.delta).startsWith('-')?'':'+')+p.delta;if(e.type==='DAMAGE_DEALT')return p.amount+(p.isCommander?' commander':'')+' damage to P'+p.defenderId;if(e.type==='COMMANDER_DAMAGE_DEALT')return p.amount+' commander damage to P'+p.defenderId;if(e.type==='COUNTER_CHANGED')return 'P'+p.playerId+' '+p.counter+' '+(p.delta>=0?'+':'')+p.delta;if(e.type==='TOKEN_COHORT_CREATED')return 'Tokens ×'+(p.cohort?.q||p.quantity||1);if(e.type==='STACK_TRIGGER_GROUP_ADDED')return 'Triggers ×'+(p.item?.count||p.count||1)+' · '+(p.item?.name||'group');if(e.type==='STACK_ITEM_ADDED')return 'Stack + '+(p.item?.name||'item');if(e.type==='STACK_ITEM_REMOVED')return p.reason==='countered'?'Countered · stack object':p.reason==='all-targets-illegal'?'Did not resolve · illegal targets':p.reason==='exiled'?'Stack object exiled':p.reason==='resolved'?'Stack object resolved':'Stack item removed';if(e.type==='SMART_PRIORITY_MODE_SET')return 'Smart Priority · '+String(p.mode||'standard').toUpperCase();if(e.type==='SMART_PRIORITY_STOPS_SET')return 'P'+(p.playerId||e.actorId)+' priority stops · '+(typeof MTGSmartPriority!=='undefined'?MTGSmartPriority.stopLabel(p.stops):'UPDATED');if(e.type==='PRIORITY_WINDOW_OPENED')return 'Priority opened · P'+(p.flow?.holder||'—');if(e.type==='PRIORITY_PASSED')return 'P'+(p.playerId||e.actorId)+' passed priority'+(p.allPassed?' · all passed':'');if(e.type==='PRIORITY_CLAIMED')return p.holdOnly?'P'+e.actorId+' declared response':'P'+e.actorId+' claimed casual response';if(e.type==='PRIORITY_WINDOW_CLOSED')return 'Priority window closed';return e.type.replaceAll('_',' ')}
function renderHost(){if(!HST)return;let panel=$('hostPanel');if(!panel)return;$('hostRoomCode').textContent=(activeRoom||'------').toUpperCase();if(hostTab==='table'){let living=players.filter(p=>!st.fallen[p.id]).length,priorityHolder=Number(st.priorityFlow?.holder||0),holderPlayer=players.find(p=>Number(p.id)===priorityHolder),holderOffline=!!priorityHolder&&holderPlayer?.connected===false;panel.innerHTML='<div class="hostGrid"><div class="hostCard"><h3>MATCH STATE</h3><div class="hostMetric">TURN '+st.turn+'</div><div class="hostMuted">P'+st.active+' · '+st.phase+' · '+(st.priority?'Priority P'+st.priority:'No priority hold')+' · '+smartPriorityMode().toUpperCase()+(st.priorityFlow?.windowId?' · '+st.priorityFlow.consecutivePassCount+'/'+st.priorityFlow.order.length+' PASSES · WINDOW '+esc(String(st.priorityFlow.windowId).slice(-10))+' · GEN '+Number(st.priorityFlow.openedAtSeq||0)+(holderOffline?' · OFFLINE HOLD P'+priorityHolder:''):'')+'</div><div class="hostPlayerActions"><button id="hostNextPhase" class="hostMini">NEXT PHASE</button><button id="hostPriorityPass" class="hostMini">'+(holderOffline?'PASS OFFLINE HOLDER':'PASS CURRENT PRIORITY')+'</button><button id="hostResolve" class="hostMini">RESOLVE TOP</button><button id="hostUndo" class="hostMini">UNDO</button><button id="hostFreeze" class="hostMini '+(rulesFrozen?'rulesFreeze':'')+'">'+(rulesFrozen?'RESUME':'RULES REVIEW')+'</button></div></div><div class="hostCard"><h3>TABLE</h3><div class="hostMetric">'+living+' / '+players.length+'</div><div class="hostMuted">players remaining · '+st.stack.length+' stack item'+(st.stack.length===1?'':'s')+' · '+st.battle.length+' tracked permanent'+(st.battle.length===1?'':'s')+'</div></div></div><div class="hostCard" style="margin-top:8px"><h3>PUBLIC STATUS</h3><div class="hostPlayerStats"><span class="hostStat">MONARCH '+(st.mon?'P'+st.mon:'—')+'</span><span class="hostStat">INITIATIVE '+(st.ini?'P'+st.ini:'—')+'</span><span class="hostStat">EVENT #'+(st.meta?.seq||0)+'</span><span class="hostStat">SYNC R'+authoritySyncRevision+' · E'+Number(roomDescriptor?.epoch||0)+'</span><span class="hostStat">MATCH '+String(st.meta?.matchId||'').slice(-8)+'</span></div></div>';$('hostNextPhase').onclick=()=>{if(rulesFrozen)return toast('Rules Review is active.');apply('advanceTurn',{},st.active,{source:'host-control',sourceActorId:st.active});renderHost()};$('hostPriorityPass').onclick=()=>{if(rulesFrozen)return toast('Rules Review is active.');let holder=Number(st.priorityFlow?.holder||0);if(!holder)return toast('No current priority holder.');if(!confirm((holderOffline?'Player '+holder+' is offline and still holds priority. ':'')+'Pass priority for Player '+holder+'? This is an explicit host recovery action; the app will never auto-pass an offline player.'))return;priorityPass(holder,{source:'host-priority-recovery'});renderHost()};$('hostResolve').onclick=()=>{if(rulesFrozen)return toast('Rules Review is active.');resolveTop({force:true,hostReason:'host-control'});renderHost()};$('hostUndo').onclick=hostUndo;$('hostFreeze').onclick=()=>{rulesFrozen=!rulesFrozen;renderHost();toast(rulesFrozen?'Rules Review — game actions paused.':'Game resumed.')};return}
if(hostTab==='players'){panel.innerHTML=players.map(p=>{let key=MTGEngine.commanderKey(p.id),incoming=Math.max(0,...Object.values(st.cmd[p.id]||{}).map(Number));return '<div class="hostPlayer"><div class="hostPlayerMain"><div class="hostPlayerName">P'+p.id+' · '+(p.name||'Player')+(st.fallen[p.id]?' · FALLEN':'')+'</div><div class="hostPlayerMeta">'+(p.commander||'No commander selected')+'</div><div class="hostPlayerStats"><span class="hostStat">Life '+(st.life[p.id]??40)+'</span><span class="hostStat">Poison '+(st.poison[p.id]||0)+'</span><span class="hostStat">Tax '+(st.tax[p.id]||0)+'</span><span class="hostStat">Casts '+(st.cmdCasts[p.id]||0)+'</span><span class="hostStat">Max CMD '+incoming+'</span></div><div class="hostPlayerActions"><button class="hostMini" data-hp="life" data-p="'+p.id+'">LIFE ±</button><button class="hostMini" data-hp="poison" data-p="'+p.id+'">POISON ±</button><button class="hostMini" data-hp="tax" data-p="'+p.id+'">TAX ±</button><button class="hostMini" data-hp="cmdCasts" data-p="'+p.id+'">CASTS ±</button><button class="hostMini" data-hcmd="'+p.id+'">CMD DAMAGE</button><button class="hostMini" data-hmon="'+p.id+'">MONARCH</button><button class="hostMini" data-hini="'+p.id+'">INITIATIVE</button><button class="hostMini danger" data-hfall="'+p.id+'">'+(st.fallen[p.id]?'RESTORE STATUS':'MARK FALLEN')+'</button></div></div></div>'}).join('');panel.querySelectorAll('[data-hp]').forEach(b=>b.onclick=()=>hostAdjustPlayer(+b.dataset.p,b.dataset.hp));panel.querySelectorAll('[data-hcmd]').forEach(b=>b.onclick=()=>hostCommanderDamage(+b.dataset.hcmd));panel.querySelectorAll('[data-hmon]').forEach(b=>b.onclick=()=>{if(st.mon!==+b.dataset.hmon)emit('STATUS_TOGGLED',{playerId:+b.dataset.hmon,status:'mon'},me,{source:'host-control'});renderHost();send({t:'state',st})});panel.querySelectorAll('[data-hini]').forEach(b=>b.onclick=()=>{if(st.ini!==+b.dataset.hini)emit('STATUS_TOGGLED',{playerId:+b.dataset.hini,status:'ini'},me,{source:'host-control'});renderHost();send({t:'state',st})});panel.querySelectorAll('[data-hfall]').forEach(b=>b.onclick=()=>{let id=+b.dataset.hfall;if(st.fallen[id]){if(!confirm('Restore Player '+id+' status only? Their departed tracked game objects will not be recreated. If MARK FALLEN was accidental and no later actions matter, use UNDO instead.'))return;emit('PLAYER_RESTORED',{playerId:id},me,{source:'host-correction'});send({t:'state',st})}else{if(!confirm('Mark Player '+id+' fallen? Their tracked owned game objects will leave the game immediately. Use UNDO if this is an accidental correction.'))return;markPlayerFallenAuthoritative(id,'host override',me,{source:'host-control'})}renderHost()});return}
if(hostTab==='stack'){panel.innerHTML='<div class="hostCard"><div class="sectionHead"><h3>AUTHORITATIVE STACK</h3><button id="hostStackResolve" class="hostMini">RESOLVE TOP</button></div><div style="margin-top:8px">'+(st.stack.length?st.stack.slice().reverse().map((x,i)=>'<div class="hostStackItem"><div><div class="hostStackType">#'+(st.stack.length-i)+' · '+String(x.kind||'item').toUpperCase()+(MTGEngine.asBigInt(x.count||'1')>1n?' · ×'+MTGEngine.formatExact(x.count):'')+'</div><div class="hostStackName">'+(x.name||'Unnamed stack object')+'</div><div class="hostMuted">Controller '+(x.controllerId?'P'+x.controllerId:'—')+' · '+(x.targets?.length||0)+' target'+((x.targets?.length||0)===1?'':'s')+' · '+(x.id||'no-id')+'</div></div><div><button class="hostMini" data-stack-why="'+x.id+'">WHY</button><button class="hostMini danger" data-stack-remove="'+x.id+'">REMOVE</button></div></div>').join(''):'<div class="hostMuted">The stack is empty.</div>')+'</div></div>';$('hostStackResolve').onclick=()=>{if(rulesFrozen)return toast('Rules Review is active.');resolveTop({force:true,hostReason:'host-stack-control'});renderHost()};panel.querySelectorAll('[data-stack-why]').forEach(b=>b.onclick=()=>{let x=st.stack.find(z=>z.id===b.dataset.stackWhy),e=(st.events||[]).slice().reverse().find(ev=>ev.payload?.item?.id===x?.id);if(e)showWhy(e.id);else toast('No calculation record for this object yet.')});panel.querySelectorAll('[data-stack-remove]').forEach(b=>b.onclick=()=>{emit('STACK_ITEM_REMOVED',{stackItemId:b.dataset.stackRemove,reason:'host-correction'},me,{source:'host-correction'});feed('Host removed an incorrect stack object.');send({t:'state',st});renderHost()});return}
if(hostTab==='log'){let ev=(st.events||[]).slice().reverse();panel.innerHTML='<div class="hostCard"><div class="sectionHead"><h3>EVENT LOG</h3><button id="hostLogUndo" class="hostMini">UNDO LAST</button></div><div class="hostLog">'+(ev.length?ev.map(e=>'<div class="hostEvent"><div class="sectionHead"><b>#'+e.seq+' · '+eventLabel(e)+'</b><div><button class="hostMini" data-event-why="'+e.id+'">WHY</button><button class="hostMini" data-rollback="'+e.seq+'">ROLLBACK</button></div></div><div class="hostEventMeta">'+e.type+' · actor P'+e.actorId+' · '+new Date(e.at).toLocaleTimeString()+'</div></div>').join(''):'<div class="hostMuted">No authoritative events yet.</div>')+'</div></div>';$('hostLogUndo').onclick=hostUndo;panel.querySelectorAll('[data-event-why]').forEach(b=>b.onclick=()=>showWhy(b.dataset.eventWhy));panel.querySelectorAll('[data-rollback]').forEach(b=>b.onclick=()=>{let seq=+b.dataset.rollback,restored=MTGEngine.rollbackToSequence(st,seq);if(!restored)return toast('That rollback point is outside the retained snapshot window.');if(!confirm('Rollback the authoritative match state to event #'+seq+'?'))return;st=restored;sync();send({t:'state',st});renderHost();toast('Rolled back to event #'+seq+'.')});return}
if(hostTab==='judge'){panel.innerHTML='<div class="judgeBlock"><div class="judgeTitle">STATE-BASED LOSS CHECKS</div>'+players.map(p=>'<div class="toggleRow"><span>P'+p.id+' · '+(p.name||'Player')+'</span><b>'+(MTGEngine.lossReason(st,p.id)||'CLEAR').toUpperCase()+'</b></div>').join('')+'</div><div class="judgeBlock"><div class="judgeTitle">PUBLIC RULES STATE</div><div class="hostPlayerStats"><span class="hostStat">Life ≤ 0</span><span class="hostStat">Poison ≥ 10</span><span class="hostStat">21 commander damage / source</span><span class="hostStat">Stack '+st.stack.length+'</span></div><div class="hostMuted" style="margin-top:9px">Judge Mode only displays public tracked information. Hidden deck/card information is not exposed here.</div></div><button id="judgeFreeze" class="btn '+(rulesFrozen?'rulesFreeze':'')+'">'+(rulesFrozen?'RESUME GAME':'FREEZE FOR RULES REVIEW')+'</button>';$('judgeFreeze').onclick=()=>{rulesFrozen=!rulesFrozen;renderHost()};return}
let prefs=hostPrefs();prefs.smartPriority=MTGSmartPriority.mode(prefs.smartPriority);panel.innerHTML='<div class="hostCard"><h3>HOST SETTINGS</h3><div class="toggleRow"><span>Smart Priority</span><button id="prefPriority" class="hostMini">'+String(prefs.smartPriority).toUpperCase()+'</button></div><div class="hostMuted" style="margin:7px 0 10px">Every priority-bearing step now uses the same rules window. RELAXED auto-yields empty-stack nonactive seats aggressively. STANDARD auto-yields only seats without a configured stop, while stack interaction still passes in sequence. FULL CONTROL auto-yields nobody. Hidden information is never inspected to decide a yield.</div><div class="hostMuted" style="margin:0 0 10px">PUBLIC STOPS · '+players.map(p=>'P'+p.id+' '+MTGSmartPriority.stopLabel(MTGSmartPriority.stopProfile(st,p.id))).join(' · ')+'</div><button id="smartPriorityQA" class="hostMini" style="margin-bottom:8px">RUN PRIORITY MATRIX</button><button id="fullRegressionQA" class="hostMini" style="margin-bottom:10px">RUN FULL REGRESSION QA</button><div class="toggleRow"><span>Assist Mode · this device</span><button id="prefAssist" class="hostMini">'+(prefs.assist?'ON':'OFF')+'</button></div><div class="hostMuted" style="margin:7px 0 8px">Private read-only coaching with REQUIRED/CONVENIENCE attention, confidence labels, exact public sources, WHY explanations, and grouped reminders. It never makes gameplay choices.</div><button id="assistModeQA" class="hostMini" style="margin-bottom:10px">RUN ASSIST MODE QA</button><div class="toggleRow"><span>Announcer Frequency</span><button id="prefAnnouncerFreq" class="hostMini">'+String(MTGAnnouncerEngine?.mode?.()||'standard').toUpperCase()+'</button></div><div class="hostMuted" style="margin:7px 0 8px">MINIMAL speaks only at major table moments. STANDARD adds readiness, critical-state and crown/initiative callouts. CINEMATIC also allows response-window flavor. Variation memory avoids repeating the same line back-to-back.</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px"><button id="announcerPreview" class="hostMini">PREVIEW PERSONALITY</button><button id="announcerQA" class="hostMini">RUN ANNOUNCER QA</button></div><div class="toggleRow"><span>Spoken Herald</span><button id="prefSpokenHerald" class="hostMini">'+(MTGSpokenHerald.status().enabled?'ON':'OFF')+'</button></div><div class="hostMuted" style="margin:7px 0 8px">Voice · '+esc(MTGSpokenHerald.status().voice)+' · '+esc(MTGSpokenHerald.status().lang)+' · Global announcements speak from the host device so a full table does not echo the same line from every phone.</div><button id="spokenHeraldPreview" class="hostMini" style="margin-bottom:10px">HEAR HERALD VOICE</button><div class="toggleRow"><span>Automatic loss checks</span><button id="prefLoss" class="hostMini">'+(prefs.autoLoss?'ON':'OFF')+'</button></div></div>';let save=()=>localStorage.setItem('mtgte_host_prefs',JSON.stringify(prefs));$('prefPriority').onclick=()=>{prefs.smartPriority=prefs.smartPriority==='relaxed'?'standard':prefs.smartPriority==='standard'?'full':'relaxed';save();setSmartPriorityMode(prefs.smartPriority);renderHost()};$('smartPriorityQA').onclick=()=>{let q=MTGSmartPriority.localQA();toast(q.ok?'Smart Priority QA passed.':'Smart Priority QA failed.');$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 77 · MULTI-CLIENT MATRIX</div><div class="whyTitle">Smart Priority '+(q.ok?'PASS':'FAIL')+'</div>'+q.checks.map(x=>'<div class="historyMatch"><span><b>'+esc(x[0])+'</b></span><strong>'+(x[1]?'✓':'!')+'</strong></div>').join('')+'</div>'};$('fullRegressionQA').onclick=()=>{let q=MTGRegressionQA.run();toast(q.ok?'Full regression QA passed.':'Regression QA found a failure.');$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">PHASE 109 · FULL REGRESSION · SHARED TABLE DISPLAY</div><div class="whyTitle">'+(q.ok?'PASS':'FAIL')+' · '+q.assertionsPassed+'/'+q.assertions+'</div><div class="hostMuted" style="margin-bottom:8px">'+q.qaModules+' behavior modules · '+q.legacySuites+' legacy suites · '+q.infraModules+' infrastructure modules</div>'+q.environmentChecks.map(x=>'<div class="historyMatch"><span><b>'+esc(x[0])+'</b></span><strong>'+(x[1]?'✓':'!')+'</strong></div>').join('')+q.groups.map(g=>'<div class="historyMatch"><span><b>'+esc(g.name)+'</b><small>'+esc(g.version||'loaded')+' · '+g.checks+' checks</small></span><strong>'+(g.ok?'✓':'!')+'</strong></div>').join('')+'</div>'};$('prefAssist').onclick=()=>{prefs.assist=!prefs.assist;save();setAssistEnabled(prefs.assist);renderHost()};if($('assistModeQA'))$('assistModeQA').onclick=runAssistModeQA;if($('prefAnnouncerFreq'))$('prefAnnouncerFreq').onclick=()=>{MTGAnnouncerEngine.cycleFrequency();renderHost();toast('Announcer frequency · '+MTGAnnouncerEngine.mode().toUpperCase())};if($('announcerPreview'))$('announcerPreview').onclick=()=>{unlockScoreAudio();MTGAnnouncerEngine.preview()};if($('prefSpokenHerald'))$('prefSpokenHerald').onclick=()=>{let on=MTGSpokenHerald.toggle();renderHost();toast('Spoken Herald · '+(on?'ON':'OFF'))};if($('spokenHeraldPreview'))$('spokenHeraldPreview').onclick=()=>{unlockScoreAudio();MTGSpokenHerald.preview()};if($('announcerQA'))$('announcerQA').onclick=()=>{let q=MTGAnnouncerEngine.localQA();toast(q.ok?'Announcer QA passed.':'Announcer QA failed.');$('modal').classList.remove('h');$('choices').innerHTML='<div class="whySheet"><div class="small">SIDE QUEST · ADAPTIVE ANNOUNCER</div><div class="whyTitle">Personality Engine '+(q.ok?'PASS':'FAIL')+'</div><div class="hostMuted" style="margin-bottom:8px">'+esc(q.version)+' · '+esc(String(q.mode).toUpperCase())+'</div>'+q.checks.map(x=>'<div class="historyMatch"><span><b>'+esc(x[0])+'</b></span><strong>'+(x[1]?'✓':'!')+'</strong></div>').join('')+'</div>'};$('prefLoss').onclick=()=>{prefs.autoLoss=!prefs.autoLoss;save();renderHost()}
}
